from typing import Any, Dict, List
from fastapi import HTTPException, status

from app.config import DISCLAIMER_TEXT
from app.tasks.base import BaseMriTask, TaskInfo, TaskSetupGuide, TaskStatus

class FutureResearchTask(BaseMriTask):
    """
    Extensible module placeholder representing future neuroimaging research tasks
    (e.g., TBI, Parkinson's Neuromelanin MRI, Brain Age, Normal Pressure Hydrocephalus).
    Status: Coming later.
    """

    task_id = "future-research"
    name = "Future Neuroimaging Research Modules"
    short_title = "Future Research"
    category = "Emerging Neuro-AI Research"
    tagline = "Roadmap modules for Traumatic Brain Injury, Parkinson’s, and Brain Age prediction"
    description = (
        "AXONOVA's modular architecture is designed for plug-and-play integration of emerging "
        "neuroimaging benchmarks. Future tasks include Susceptibility-Weighted Imaging (SWI) for TBI microhemorrhages, "
        "neuromelanin-sensitive MRI in Parkinson's, and healthy Brain Age regression."
    )
    supported_scan_types = ["MRI"]
    required_sequences = ["SWI", "Diffusion Tensor Imaging (DTI)", "Neuromelanin-MRI", "T1 3D Volumetric"]
    supported_orientations = ["Axial", "Coronal", "Sagittal"]
    supported_formats = [".jpg", ".jpeg", ".png"]
    limitations = [
        "In Development: This module is a research roadmap item.",
        "Pipelines must define task-specific loss functions, held-out validation cohorts, and leak-free split policies prior to enablement.",
    ]
    disclaimer = DISCLAIMER_TEXT

    def is_ready(self) -> bool:
        return False

    def get_status(self) -> TaskStatus:
        return "coming_later"

    def get_class_labels(self) -> List[str]:
        return []

    def get_task_info(self) -> TaskInfo:
        return TaskInfo(
            task_id=self.task_id,
            name=self.name,
            short_title=self.short_title,
            category=self.category,
            status=self.get_status(),
            tagline=self.tagline,
            description=self.description,
            supported_scan_types=self.supported_scan_types,
            required_sequences=self.required_sequences,
            supported_orientations=self.supported_orientations,
            supported_formats=self.supported_formats,
            class_labels=[],
            model_loaded=False,
            model_name=None,
            model_version=None,
            input_shape=None,
            trainable_parameters=None,
            evaluation_available=False,
            overall_accuracy=None,
            limitations=self.limitations,
            disclaimer=self.disclaimer,
            setup_guide=None,
        )

    def get_model_info(self) -> Dict[str, Any]:
        return {
            "loaded": False,
            "task_id": self.task_id,
            "training_status": "Coming later",
            "supported_classes": [],
            "supported_scan_type": "MRI",
            "evaluation_available": False,
            "disclaimer": self.disclaimer,
        }

    def get_evaluation(self) -> Dict[str, Any]:
        return {
            "evaluated": False,
            "task_id": self.task_id,
            "reason": "Future research module roadmap item.",
            "disclaimer": self.disclaimer,
        }

    def get_dataset_info(self) -> Dict[str, Any]:
        return {
            "available": False,
            "task_id": self.task_id,
            "dataset_name": "Future Neuroimaging Benchmarks",
            "source": "Planned Future Releases",
            "total_images": 0,
            "class_distribution": {},
            "split_counts": {},
            "disclaimer": self.disclaimer,
        }

    def predict(
        self,
        file_bytes: bytes,
        scan_type: str,
        orientation: str,
        filename: str = "uploaded_scan.jpg",
    ) -> Dict[str, Any]:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Future research tasks are in the roadmap and not currently active.",
        )
